#include <jsd/engine.hpp>
#include <iostream>
#include <type_traits>
#include <limits>
using namespace jsd;
int main(){
    int checks=0,failures=0;
    auto check=[&](bool ok,const char *name){++checks;if(!ok){++failures;std::cerr<<"FAIL: "<<name<<'\n';}};
    auto near=[](double a,double b,double e=1e-3){return std::abs(a-b)<e;};
    auto rejects=[&](auto call,const char *name){bool rejected=false;try{call();}catch(const std::invalid_argument &){rejected=true;}check(rejected,name);};
    static_assert(std::is_same_v<decltype(si::Mass{}*si::Acceleration{}),si::Force>);
    check(near((si::kilograms(10)*si::standardGravity).value(),98.0665),"SI dimensional force");
    check(near(si::millimetres(1000).value(),1),"SI millimetres conversion");
    check(near(si::dampingFactor(si::Damping{2},si::seconds(.5)),std::exp(-1.)),"exponential SI damping");
    WorldSettings config;config.workers=1;config.gravityMps2={};
    PhysicsWorld world(config);
    BodySettings s;s.position={0,10,0};s.halfExtent={1,2,3};s.mass=12;s.linearDampingPerSecond=s.angularDampingPerSecond=0;
    auto box=world.box(s);auto m=world.massProperties(box);
    check(near(m.volumeM3,48),"box SI volume");check(near(m.massKg,12),"explicit mass");
    check(near(m.inertiaDiagonalKgM2.x,52)&&near(m.inertiaDiagonalKgM2.y,40)&&near(m.inertiaDiagonalKgM2.z,20),"box analytic inertia tensor");
    world.impulse(box,{24,0,0});check(near(world.state(box).velocity.x,2),"impulse divided by mass");
    check(near(world.kineticEnergyJoules(box),24),"translational energy joules");
    world.velocity(box,{});world.force(box,{120,0,0});world.step(.1f);
    check(near(world.state(box).velocity.x,1),"force accelerates over all internal substeps");
    world.step(.1f);check(near(world.state(box).velocity.x,1),"one-interval force clears");
    world.continuousForce(box,{120,0,0});world.step(.1f);world.step(.1f);
    check(near(world.state(box).velocity.x,3),"persistent force spans intervals");world.clearForces(box);
    world.angularImpulse(box,{52,0,0});check(near(world.state(box).angularVelocity.x,1),"angular impulse uses inertia");
    world.angularVelocity(box,{});world.torque(box,{52,0,0});world.step(.1f);
    check(near(world.state(box).angularVelocity.x,.1,.002),"torque angular acceleration");
    world.teleport(box,{0,10,0});world.impulseAt(box,{12,0,0},{0,11,0});
    check(near(world.state(box).velocity.x,1)&&world.state(box).angularVelocity.z<-.59,"off-centre impulse translates and rotates");
    world.teleport(box,{0,10,0});world.forceAt(box,{120,0,0},{0,11,0});world.step(.1f);
    check(world.state(box).angularVelocity.z<-.59,"force at point creates torque");
    world.remove(box);rejects([&]{world.state(box);},"stale handles rejected");
    s.position={20,10,0};s.massMode=MassMode::Density;s.densityKgPerM3=500;
    auto sphere=world.sphere(s,2);m=world.massProperties(sphere);
    check(near(m.volumeM3,4.*rf::pi*8/3,1e-4),"sphere analytic volume");check(near(m.massKg,500*m.volumeM3,.01),"density derived mass");
    check(near(m.inertiaDiagonalKgM2.x,.4*m.massKg*4,.01),"sphere analytic inertia");
    world.remove(sphere);auto cylinder=world.cylinder(s,2,1);m=world.massProperties(cylinder);
    check(near(m.volumeM3,4*rf::pi,1e-4)&&near(m.inertiaDiagonalKgM2.y,.5*m.massKg,.01),"cylinder volume and axial inertia");world.remove(cylinder);
    auto capsule=world.capsule(s,2,1);m=world.massProperties(capsule);
    check(near(m.volumeM3,4*rf::pi+4.*rf::pi/3,1e-4),"capsule volume includes end caps");world.remove(capsule);
    s.massMode=MassMode::ExplicitKilograms;s.mass=1;s.halfExtent={.5f,.5f,.5f};s.position={0,100,0};
    auto falling=world.sphere(s,.5f);world.gravity({0,-9.80665f,0});for(int i=0;i<120;i++)world.step(1.f/120);
    auto f=world.state(falling);check(near(f.velocity.y,-9.80665,.002),"standard gravity m/s2");
    check(near(f.position.y,100-9.80665/2,.05),"one second freefall trajectory");
    check(near(world.potentialEnergyJoules(falling),9.80665*f.position.y,.01),"potential energy joules");world.remove(falling);world.gravity({});
    s.linearDampingPerSecond=2;s.angularDampingPerSecond=2;auto damped=world.sphere(s,.5f);world.velocity(damped,{10,0,0});world.angularVelocity(damped,{0,10,0});
    for(int i=0;i<120;i++)world.step(1.f/120);
    check(near(world.state(damped).velocity.x,10*std::exp(-2.),1e-4),"linear damping exact exponential decay");
    check(near(world.state(damped).angularVelocity.y,10*std::exp(-2.),1e-4),"angular damping exact exponential decay");world.remove(damped);
    s.linearDampingPerSecond=s.angularDampingPerSecond=0;s.dragCoefficient=1;s.dragAreaM2=1;auto drag=world.sphere(s,.5f);world.velocity(drag,{10,0,0});
    world.step(.01f);check(world.state(drag).velocity.x<10&&world.state(drag).velocity.x>9,"aerodynamic drag opposes relative velocity");world.remove(drag);
    s.dragAreaM2=10000;auto strongDrag=world.sphere(s,.5f);world.velocity(strongDrag,{100,0,0});world.step(.25f);
    check(world.state(strongDrag).velocity.x>=0&&world.state(strongDrag).velocity.x<.01,"strong drag cannot reverse or destabilize velocity");world.remove(strongDrag);
    s.dragCoefficient=s.dragAreaM2=0;
    world.resetClock();auto ticker=world.box(s);int ticks=0;auto a=world.advance(1./240,[&](auto &,float){++ticks;});check(a.steps==0,"sub-tick frame accumulates");
    a=world.advance(1./240,[&](auto &w,float){++ticks;w.force(ticker,{120,0,0});});
    check(a.steps==1&&ticks==1&&near(world.state(ticker).velocity.x,1),"fixed-step callback applies force once per tick");
    auto mid=world.interpolatedState(ticker,.5f);check(mid.position.x>0&&mid.position.x<world.state(ticker).position.x,"render interpolation between solver states");world.remove(ticker);
    config.maxStepsPerAdvance=2;PhysicsWorld budget(config);auto b=budget.advance(.1);check(b.steps==2&&b.behind&&b.pendingSeconds>.08,"catch-up budget preserves simulation time");for(int i=0;i<5;i++)b=budget.advance(0);check(!b.behind&&b.pendingSeconds<1e-8,"backlog catches up without dropped time");
    BodySettings wall;wall.motion=MotionType::Static;wall.position={3,2,0};wall.halfExtent={.05f,2,3};auto obstacle=world.box(wall);
    BodySettings actor;actor.motion=MotionType::Kinematic;actor.position={0,2,0};auto controlled=world.box(actor);
    auto move=world.moveKinematic(controlled,{10,2,0},{},.1f);check(move.blocked&&move.blocker==obstacle&&move.acceptedPosition.x<2.46f,"shape sweep blocks cinematic motion at thin wall");
    world.step(.1f);check(world.state(controlled).position.x<2.46f&&world.state(controlled).position.x>2.4f,"solver reaches accepted target without tunnelling");
    world.step(.1f);check(rf::length(world.state(controlled).velocity)<1e-5,"kinematic actor stops after target interval");
    move=world.moveKinematic(controlled,{0,2,0},{},.1f);world.step(.1f);check(!move.blocked&&near(world.state(controlled).position.x,0),"movement away from blocker succeeds");
    auto ray=world.rayCast({0,2,0},{8,2,0},{controlled});check(ray&&ray->body==obstacle&&ray->normal.x<-.99,"occlusion query returns blocker and outward normal");
    check(!world.rayCast({0,8,0},{8,8,0}),"clear sight line unblocked");
    BodySettings sensor=wall;sensor.sensor=true;sensor.position={1,2,0};auto trigger=world.box(sensor);
    move=world.moveKinematic(controlled,{2,2,0},{},.1f);world.step(.1f);check(!move.blocked,"sensors do not block controlled motion");
    ray=world.rayCast({0,2,0},{2,2,0},{controlled,true});check(ray&&ray->body==trigger,"queries optionally include sensors");world.remove(trigger);
    world.teleport(controlled,{0,2,0});KinematicMotor motor;for(int i=0;i<120;i++){motor.moveTowards(world,controlled,{10,2,0},1.f/120);world.step(1.f/120);}
    check(world.state(controlled).position.x<2.46f,"acceleration limited motor respects obstacles");world.remove(obstacle);
    for(int i=0;i<720;i++){motor.moveTowards(world,controlled,{10,2,0},1.f/120);world.step(1.f/120);}
    check(near(world.state(controlled).position.x,10,.003),"motor resumes and arrives after blocker removed");
    world.motionType(controlled,MotionType::Dynamic);world.gravity({0,-9.80665f,0});world.step(.1f);check(world.state(controlled).velocity.y<-.9,"cinematic prop becomes dynamic on release");
    rejects([&]{world.step(-.1f);},"negative duration rejected");rejects([&]{world.advance(std::numeric_limits<double>::quiet_NaN());},"NaN clock rejected");s.mass=-1;rejects([&]{world.box(s);},"negative mass rejected");
    PhysicsWorld impact(config);BodySettings left;left.position={-2,0,0};left.mass=1;left.friction=0;left.restitution=1;left.linearDampingPerSecond=left.angularDampingPerSecond=0;left.continuous=true;
    auto small=impact.sphere(left,.5f);left.position={2,0,0};left.mass=3;auto heavy=impact.sphere(left,.5f);impact.velocity(small,{4,0,0});
    for(int i=0;i<120;i++)impact.step(1.f/120);
    auto vs=impact.state(small).velocity.x,vh=impact.state(heavy).velocity.x;
    check(near(vs,-2,.03)&&near(vh,2,.03),"elastic collision respects unequal body masses");
    check(near(vs+3*vh,4,.01),"collision conserves linear momentum");
    check(near(impact.kineticEnergyJoules(small)+impact.kineticEnergyJoules(heavy),8,.03),"elastic collision conserves kinetic energy");
    WorldSettings clockConfig=config;clockConfig.maxStepsPerAdvance=32;
    PhysicsWorld thirty(clockConfig),fast(clockConfig);BodySettings clockBody;clockBody.position={0,20,0};clockBody.linearDampingPerSecond=0;
    auto slowBody=thirty.box(clockBody),fastBody=fast.box(clockBody);thirty.gravity({0,-9.80665f,0});fast.gravity(thirty.gravity());
    for(int i=0;i<30;i++)thirty.advance(1./30);for(int i=0;i<144;i++)fast.advance(1./144);
    check(rf::distance(thirty.state(slowBody).position,fast.state(fastBody).position)<1e-6f&&thirty.statistics().simulationSteps==120&&fast.statistics().simulationSteps==120,"fixed physics state independent of 30 or 144 Hz rendering");
    PhysicsWorld rotationWorld(config);BodySettings ceiling;ceiling.motion=MotionType::Static;ceiling.position={0,4,0};ceiling.halfExtent={.5f,.5f,.5f};rotationWorld.box(ceiling);
    BodySettings rod;rod.motion=MotionType::Kinematic;rod.halfExtent={2,.1f,.1f};rod.position={0,2,0};auto longBody=rotationWorld.box(rod);
    auto rotated=rotationWorld.moveKinematic(longBody,rod.position,{0,0,.70710678f,.70710678f},.1f);
    check(rotated.blocked,"conservative angular sweep blocks a rod rotating into an obstacle");
    rotationWorld.teleport(longBody,{30,2,0});rotationWorld.moveKinematic(longBody,{34,2,0},{},1);rotationWorld.step(.1f);
    float releaseSpeed=rotationWorld.state(longBody).velocity.x;rotationWorld.motionType(longBody,MotionType::Dynamic);
    check(releaseSpeed>3.9f&&near(rotationWorld.state(longBody).velocity.x,releaseSpeed),"kinematic release preserves instantaneous linear velocity");
    rotationWorld.motionType(longBody,MotionType::Kinematic);
    rotationWorld.teleport(longBody,{30,2,0});rotated=rotationWorld.moveKinematic(longBody,{30,2,0},{0,0,.70710678f,.70710678f},.1f);rotationWorld.step(.1f);
    check(!rotated.blocked&&std::abs(rotationWorld.state(longBody).rotation.z)>.7,"unobstructed kinematic rotation reaches target");
    check(world.statistics().simulationSteps>0,"physics statistics count actual ticks");
    std::cout<<checks<<" physics checks, "<<failures<<" failures\n";return failures?1:0;
}
